4	import { SIZE } from "./vocab.mjs";
5	import * as shell from "./parts/shell.mjs";
6	import * as roofs from "./parts/roofs.mjs";
7	import * as facade from "./parts/facade.mjs";
8	import * as entry from "./parts/entry-garage.mjs";
9	import * as site from "./parts/site.mjs";
10	import * as details from "./parts/details.mjs";
11	import * as room1 from "./parts/room-1.mjs";
12	import * as room2 from "./parts/room-2.mjs";
13	import * as room3 from "./parts/room-3.mjs";
14	import * as room4 from "./parts/room-4.mjs";
15	import * as room5 from "./parts/room-5.mjs";
16	import * as room6 from "./parts/room-6.mjs";
17	import * as room7 from "./parts/room-7.mjs";
18	import * as room8 from "./parts/room-8.mjs";
19	import * as room9 from "./parts/room-9.mjs";
20	import * as room10 from "./parts/room-10.mjs";
21	import * as room11 from "./parts/room-11.mjs";
22	import * as room12 from "./parts/room-12.mjs";
23	import * as room13 from "./parts/room-13.mjs";
24	import * as room14 from "./parts/room-14.mjs";
25	import * as room15 from "./parts/room-15.mjs";
26	import * as room16 from "./parts/room-16.mjs";
27	
28	const out = process.argv[2];
29	if (!out) {
30	  console.error("usage: node build.mjs <out.nbt>");
31	  process.exit(2);
32	}
33	
